package br.com.brindespro;
import br.com.brindespro.catalog.*;import br.com.brindespro.security.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.mock.web.MockMultipartFile;import org.springframework.mock.web.MockHttpSession;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import java.util.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class QuoteFlowIntegrationTest { @Autowired MockMvc mvc;@Autowired ProductRepository products;@Autowired ObjectMapper json;@Autowired AdminUserRepository users;@Autowired PasswordEncoder passwords;
 @Test void registersQuoteAndProtectsPrivateFiles()throws Exception {Product p=products.findBySlugAndActiveTrue("garrafa-termica-inox-500ml").orElseThrow();byte[] png={(byte)137,80,78,71,13,10,26,10,0};MockMultipartFile logo=new MockMultipartFile("file","logo.png","image/png",png);String upload=mvc.perform(multipart("/api/files").file(logo).with(csrf())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();long fileId=json.readTree(upload).get("id").asLong();String token=json.readTree(upload).get("token").asText();mvc.perform(get("/api/files/{id}",fileId)).andExpect(status().is4xxClientError());Map<String,Object> line=Map.of("productId",p.id,"variantId",p.variants.iterator().next().id,"quantity",100,"engraving","Laser","printingPosition","Frente","deadline","Padrão","logoFileId",fileId,"logoToken",token);Map<String,Object> body=Map.of("customerName","Cliente Teste","company","Empresa Teste","phone","11999999999","email","teste@example.com","notes","Teste","items",List.of(line));mvc.perform(post("/api/quotes").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body))).andExpect(status().isOk()).andExpect(jsonPath("$.number").isNotEmpty()).andExpect(jsonPath("$.total").value(1890.00));}
 @Test void rejectsFileAssociationWithoutUploadToken()throws Exception {Product p=products.findBySlugAndActiveTrue("garrafa-termica-inox-500ml").orElseThrow();byte[] png={(byte)137,80,78,71,13,10,26,10,0};MockMultipartFile logo=new MockMultipartFile("file","logo.png","image/png",png);String upload=mvc.perform(multipart("/api/files").file(logo).with(csrf())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();long fileId=json.readTree(upload).get("id").asLong();Map<String,Object> line=Map.of("productId",p.id,"variantId",p.variants.iterator().next().id,"quantity",100,"engraving","Laser","printingPosition","Frente","deadline","Padrão","logoFileId",fileId,"logoToken","invalid-token");Map<String,Object> body=Map.of("customerName","Cliente Teste","company","Empresa Teste","phone","11999999999","email","teste@example.com","items",List.of(line));mvc.perform(post("/api/quotes").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body))).andExpect(status().isBadRequest());}
 @Test void adminRequiresSession()throws Exception {mvc.perform(get("/api/admin/dashboard")).andExpect(status().is4xxClientError());String email="integration-admin@example.com";if(users.findByEmail(email).isEmpty())users.save(new AdminUser(email,passwords.encode("integration-password-2026"),"Teste"));String login=json.writeValueAsString(Map.of("email",email,"password","integration-password-2026"));MockHttpSession session=(MockHttpSession)mvc.perform(post("/api/auth/login").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(login)).andExpect(status().isOk()).andReturn().getRequest().getSession(false);mvc.perform(get("/api/admin/dashboard").session(session)).andExpect(status().isOk());}
 @Test void customerTracksOwnOrderAndAdminRecordsStatusHistory()throws Exception {Product p=products.findBySlugAndActiveTrue("garrafa-termica-inox-500ml").orElseThrow();Map<String,Object> line=Map.of("productId",p.id,"variantId",p.variants.iterator().next().id,"quantity",100,"engraving","Laser","printingPosition","Frente","deadline","Padrão");Map<String,Object> body=Map.of("customerName","Pedido Teste","company","Empresa Teste","phone","11999999999","email","pedido@example.com","notes","","items",List.of(line));String created=mvc.perform(post("/api/orders").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body))).andExpect(status().isOk()).andExpect(jsonPath("$.orderStatus").value("RECEBIDO")).andReturn().getResponse().getContentAsString();long id=json.readTree(created).get("id").asLong();String number=json.readTree(created).get("number").asText();mvc.perform(get("/api/orders/track").param("number",number).param("email","other@example.com")).andExpect(status().isNotFound());mvc.perform(get("/api/orders/track").param("number",number).param("email","pedido@example.com")).andExpect(status().isOk()).andExpect(jsonPath("$.history[0].status").value("RECEBIDO"));String email="orders-admin@example.com";if(users.findByEmail(email).isEmpty())users.save(new AdminUser(email,passwords.encode("integration-password-2026"),"Pedidos"));MockHttpSession session=(MockHttpSession)mvc.perform(post("/api/auth/login").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("email",email,"password","integration-password-2026")))).andExpect(status().isOk()).andReturn().getRequest().getSession(false);Map<String,String> update=Map.of("status","EM_PRODUCAO","internalNote","Separado para produção","expectedDeliveryDate","2026-12-20","trackingCode","");mvc.perform(patch("/api/admin/orders/{id}/status",id).session(session).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(update))).andExpect(status().isOk()).andExpect(jsonPath("$.order.orderStatus").value("EM_PRODUCAO"));mvc.perform(get("/api/orders/track").param("number",number).param("email","pedido@example.com")).andExpect(status().isOk()).andExpect(jsonPath("$.history[1].status").value("EM_PRODUCAO"));}
}
